package com.workworth.earnings.api.dto; import com.workworth.earnings.persistence.WorkdayEarning; import java.math.*; import java.time.LocalDate;
public record EarningResponse(LocalDate localDate,String status,BigDecimal amount,String currencyCode,long economicSeconds){public static EarningResponse from(WorkdayEarning e){return new EarningResponse(e.getLocalDate(),e.getStatus().name(),e.getRawAmount()==null?null:e.getRawAmount().setScale(2,RoundingMode.HALF_UP),e.getCurrencyCode(),e.getEconomicSeconds());}}
